-NS_IMETHODIMP
-nsMsgMaildirStore::DiscardNewMessage(nsIOutputStream* aOutputStream,
-                                     nsIMsgDBHdr* aNewHdr) {
-  NS_ENSURE_ARG_POINTER(aOutputStream);
